// OAB Seccional URLs por estado
// Cada seccional tem um diretório público de advogados/escritórios
const seccionais = [
  { state: 'SP', name: 'OAB-SP', url: 'https://www.oabsp.org.br/servicos/advogados', searchUrl: 'https://www.oabsp.org.br/servicos/advogados?SearchableText=escritorio&b_start:int={offset}', resultsPerPage: 20, estimatedTotal: 15000 },
  { state: 'RJ', name: 'OAB-RJ', url: 'https://www.oabrj.org.br/advogados', searchUrl: 'https://www2.oabrj.org.br/scripts/consulta_adv.asp?tipo=nome&nome=&pagina={page}', resultsPerPage: 30, estimatedTotal: 8000 },
  { state: 'MG', name: 'OAB-MG', url: 'https://www.oabmg.org.br/advogado', searchUrl: 'https://www.oabmg.org.br/advogado/busca?page={page}', resultsPerPage: 20, estimatedTotal: 6000 },
  { state: 'PR', name: 'OAB-PR', url: 'https://www.oabpr.org.br/', searchUrl: 'https://www.oabpr.org.br/servicos-ao-advogado/consulta-de-advogados/?page={page}', resultsPerPage: 20, estimatedTotal: 4000 },
  { state: 'RS', name: 'OAB-RS', url: 'https://www.oabrs.org.br/', searchUrl: 'https://www.oabrs.org.br/advogados?page={page}', resultsPerPage: 20, estimatedTotal: 4000 },
];

// Configuração da execução
const targetStates = $input.first().json.states || ['SP']; // Default: começa por SP
const maxPagesPerRun = $input.first().json.max_pages || 50; // Limita pra não sobrecarregar

const targets = seccionais
  .filter(s => targetStates.includes(s.state))
  .map(s => ({
    ...s,
    pages: Array.from({ length: maxPagesPerRun }, (_, i) => i + 1)
  }));

return targets.map(t => ({ json: t }));

// Parse HTML response to extract lawyer/firm data
// This is a generic parser - needs adaptation per seccional
const html = $input.first().json.body || '';
const state = $input.first().json.state || 'SP';

// Generic extraction patterns for OAB directories
// These need to be customized per seccional website structure
const results = [];

// Pattern 1: Look for structured data (name + OAB number + city)
const namePattern = /(?:nome|advogado)[^>]*>([^<]+)</gi;
const oabPattern = /(?:oab|inscri)[^>]*>([^<]*\d+[^<]*)</gi;
const cityPattern = /(?:cidade|comarca|local)[^>]*>([^<]+)</gi;

// Try to extract table rows or list items with lawyer info
const rowPattern = /<tr[^>]*>([\s\S]*?)<\/tr>/gi;
let match;

while ((match = rowPattern.exec(html)) !== null) {
  const row = match[1];
  const cells = row.match(/<td[^>]*>([\s\S]*?)<\/td>/gi) || [];

  if (cells.length >= 2) {
    const cleanText = (html) => html.replace(/<[^>]+>/g, '').trim();
    const name = cleanText(cells[0] || '');
    const oabNumber = cleanText(cells[1] || '');
    const city = cells[2] ? cleanText(cells[2]) : '';
    const specialty = cells[3] ? cleanText(cells[3]) : '';

    if (name && name.length > 3 && !name.includes('Nome')) {
      results.push({
        full_name: name,
        oab_number: oabNumber,
        oab_state: state,
        city: city,
        specialty: specialty,
        source: `oab_${state.toLowerCase()}`,
        raw_url: $input.first().json.url
      });
    }
  }
}

// Fallback: try div-based layouts
if (results.length === 0) {
  const divPattern = /<div[^>]*class="[^"]*(?:advogado|resultado|item)[^"]*"[^>]*>([\s\S]*?)<\/div>/gi;
  while ((match = divPattern.exec(html)) !== null) {
    const block = match[1];
    const nameMatch = block.match(/(?:nome|title)[^>]*>([^<]+)/i) || block.match(/<(?:h[2-4]|strong|b)[^>]*>([^<]+)/i);
    if (nameMatch) {
      results.push({
        full_name: nameMatch[1].trim(),
        oab_state: state,
        source: `oab_${state.toLowerCase()}`,
        raw_html_snippet: block.substring(0, 200)
      });
    }
  }
}

console.log(`Extracted ${results.length} records from ${state} page`);
return results.map(r => ({ json: r }));

// Transform OAB records into CRM lead format
const items = $input.all();
const leads = items.map(item => {
  const data = item.json;

  // Split full name into first/last
  const nameParts = (data.full_name || '').split(' ');
  const firstName = nameParts[0] || '';
  const lastName = nameParts.slice(1).join(' ') || '';

  // Try to extract company from name patterns
  // E.g., "Silva & Associados" or "Escritório Mendes"
  let companyName = null;
  if (data.full_name && (data.full_name.includes('&') || data.full_name.includes('Escritório') || data.full_name.includes('Associados'))) {
    companyName = data.full_name;
  }

  return {
    json: {
      first_name: firstName,
      last_name: lastName,
      company_name: companyName,
      source: data.source,
      status: 'new',
      industry: 'legal',
      role: 'Advogado',
      tags: ['oab-scrape', data.oab_state || 'unknown'].filter(Boolean),
      custom_fields: {
        oab_number: data.oab_number || null,
        oab_state: data.oab_state || null,
        city: data.city || null,
        specialty: data.specialty || null,
        scraped_at: new Date().toISOString()
      }
    }
  };
}).filter(l => l.json.first_name.length > 1);

return leads;
